(function(){'use strict';const routes=Array.from(document.querySelectorAll('[data-route]')),intro=document.getElementById('connection-intro'),status=document.getElementById('connection-status');let initialized=false;function show(){let id;try{id=decodeURIComponent(location.hash.slice(1));}catch{id='invalid';}if(id==='lesson-main'){if(initialized)return;id='';}initialized=true;const selected=routes.find(r=>r.id===id);for(const r of routes)r.hidden=r!==selected;intro.hidden=!!selected;status.textContent=selected?'连接与设置 · 按自己的界面与权限核对':id?'未找到这条路线，请重新选择。':'';for(const a of document.querySelectorAll('aside nav a')){if(a.getAttribute('href')==='#'+id)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}if(selected){selected.setAttribute('tabindex','-1');selected.focus({preventScroll:true});selected.scrollIntoView({block:'start'});}}window.addEventListener('hashchange',show);show();const menu=document.querySelector('.chapter-menu');if(window.matchMedia?.('(max-width:760px)').matches)menu.open=false;for(const b of document.querySelectorAll('[data-copy]'))b.addEventListener('click',async()=>{const status=document.getElementById(b.dataset.copy+'-status');try{await navigator.clipboard.writeText(document.getElementById(b.dataset.copy).textContent);status.textContent='已复制。执行前请核对范围和权限。';}catch{status.textContent='复制未获允许，请选中上方文字手动复制。';}});})();
